function score(book: Book, input: UserInput, hasMemory = true): BookScore {
  const topic = book.topic === input.goal ? 1 : .72;
  const levels = { beginner: 1, intermediate: 2, advanced: 3 };
  const diff = Math.abs(levels[book.difficulty] - levels[input.difficulty]);
  const difficulty = diff === 0 ? 1 : diff === 1 ? .6 : .2;
  const dailyPages = input.time_per_day / 3;
  const ideal = book.pages / 14;
  const time = ideal >= dailyPages * .5 && ideal <= dailyPages * 1.5 ? .7 : .4;
  let preference = book.language === input.language ? .7 : .4;
  if (hasMemory && book.case_ratio >= .6) preference = Math.min(1, preference + .15);
  if (hasMemory && book.pages <= 350) preference = Math.min(1, preference + .15);
  const total = topic * 30 + difficulty * 25 + time * 20 + preference * 20;
  return { book, total_score: Math.round(total * 10) / 10, topic_score: topic, difficulty_score: difficulty, time_score: time, preference_score: preference, rejection_penalty: 0, explanation: `${topic >= .9 ? "主题高度匹配" : "主题相关"}；${time >= .7 ? "符合每日阅读节奏" : "需要更长周期"}；${preference >= .8 ? "符合案例与篇幅偏好" : "可作为补充阅读"}` };
}

