export function getMockBooks() { return [...books]; }
export function getMockMemories(userId: string) { return memories.filter((m) => m.user_id === userId); }
export function deleteMockMemory(userId: string, id: string) { memories = memories.filter((m) => !(m.user_id === userId && m.id === id)); }
export function writeMockMemory(userId: string, feedback: string): Memory {
  const field = feedback.includes("厚") || feedback.includes("短") ? "pages" : feedback.includes("英文") || feedback.includes("中文") ? "language" : "prefer_cases";
  const memory: Memory = { id: `mem_${Date.now()}`, user_id: userId, type: "preference", field, value: field === "pages" ? "prefer_short" : field === "language" ? "prefer_chinese" : true, confidence: .87, source: feedback, created_at: new Date().toISOString(), usage_count: 0 };
  memories = [memory, ...memories];
  return memory;
}

export function makeRecommendation(input: UserInput, userId: string): RecommendationResponse {
  const eligibleDifficulties: Record<UserInput["difficulty"], Book["difficulty"][]> = {
    beginner: ["beginner"],
    intermediate: ["beginner", "intermediate"],
    advanced: ["beginner", "intermediate", "advanced"],
  };
  const allowed = eligibleDifficulties[input.difficulty];
  let relevant = books.filter((b) => b.topic === input.goal && allowed.includes(b.difficulty));
  if (relevant.length === 0) relevant = [...books];
  const scored = relevant.map((b) => score(b, input, true)).sort((a, b) => b.total_score - a.total_score).slice(0, 5);
  return { books: scored, memories_used: getMockMemories(userId).slice(0, 3), explanation: "根据你的学习目标与每日时间预算，从书库中筛选最匹配的书目，并参考你的长期偏好（语言、篇幅、案例占比）排序。", agent_trace: mockTrace };
}

export function makeComparison(userId: string): CompareResponse {
  const input: UserInput = { goal: "Python基础", difficulty: "beginner", time_per_day: 30, language: "zh" };
  const relevant = books.filter((b) => [1, 2, 3, 4].includes(b.id));
  const first = relevant.map((b) => score(b, input, false)).sort((a, b) => b.total_score - a.total_score);
  const second = relevant.map((b) => score(b, input, true)).sort((a, b) => b.total_score - a.total_score);
  return { user_id: userId, feedback: "书太厚了，我更喜欢案例多、篇幅短的内容。", memory_saved: getMockMemories(userId)[1] ?? memories[0], first_recommendation: { books: first, explanation: "基于显式条件生成的初始路线。", memories_used: 0 }, second_recommendation: { books: second, explanation: "短篇、案例驱动的书籍获得更高排序。", memories_used: 3 }, comparison: { memory_added: "pages, language, prefer_cases", impact: "短篇实战书籍上升，长篇理论书籍下降" } };
}
